142: function initStars() {
143:   const canvas = $('#starfield');
144:   const ctx = canvas.getContext('2d');
145:   const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
146:   let w = 0, h = 0, dpr = Math.min(window.devicePixelRatio || 1, 2);
147:   let stars = [], shooting = null, last = performance.now();
148:   function resize() {
149:     w = window.innerWidth; h = window.innerHeight;
150:     canvas.width = w * dpr; canvas.height = h * dpr;
151:     canvas.style.width = w + 'px'; canvas.style.height = h + 'px';
152:     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
153:     const count = Math.min(220, Math.round((w * h) / 9000));
154:     stars = Array.from({ length: count }, () => ({
155:       x: Math.random() * w, y: Math.random() * h,
156:       r: Math.random() * 1.2 + 0.25,
157:       a: Math.random() * 0.55 + 0.18,
158:       sp: Math.random() * 0.014 + 0.003,
159:       ph: Math.random() * Math.PI * 2,
160:       hue: Math.random() < 0.16 ? '#e8c987' : Math.random() < 0.4 ? '#c7d6ff' : '#ffffff',
161:     }));
162:   }
163:   function draw(t) {
164:     ctx.clearRect(0, 0, w, h);
165:     const dt = reduced ? 0 : Math.min(48, t - last); last = t;
166:     for (const s of stars) {
167:       s.ph += s.sp * (dt / 16.7);
168:       const alpha = s.a * (0.6 + 0.4 * Math.sin(s.ph));
169:       ctx.globalAlpha = alpha;
170:       ctx.fillStyle = s.hue;
171:       ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2); ctx.fill();
172:       if (s.r > 1.05) {
173:         ctx.globalAlpha = alpha * 0.35;
174:         ctx.fillRect(s.x - 3, s.y - 0.3, 6, 0.6);
175:         ctx.fillRect(s.x - 0.3, s.y - 3, 0.6, 6);
176:       }
177:     }
178:     if (!reduced) {
179:       if (!shooting && Math.random() < 0.0025) {
180:         shooting = { x: Math.random() * w * 0.7 + w * 0.15, y: Math.random() * h * 0.35, vx: 2.6 + Math.random() * 2, vy: 1.4 + Math.random(), life: 1 };
181:       }
182:       if (shooting) {
183:         shooting.x += shooting.vx * 4; shooting.y += shooting.vy * 4; shooting.life -= 0.012;
184:         ctx.globalAlpha = Math.max(0, shooting.life) * 0.8;
185:         ctx.strokeStyle = '#f5e7c2'; ctx.lineWidth = 1.2;
186:         ctx.beginPath(); ctx.moveTo(shooting.x, shooting.y); ctx.lineTo(shooting.x - 70, shooting.y - 36); ctx.stroke();
187:         if (shooting.life <= 0) shooting = null;
188:       }
189:     }
190:     ctx.globalAlpha = 1;
191:     if (!reduced) requestAnimationFrame(draw);
192:   }
193:   resize();
194:   window.addEventListener('resize', resize);
195:   if (reduced) draw(0); else requestAnimationFrame(draw);
196: }
