775: function closeBtn() { return `<button class="modal-close" data-close aria-label="${esc(t('Close'))}">${icon('close')}</button>`; }
776: function affordableEffects(effects = {}) {
777:   for (const k of ['faith', 'power']) {
778:     if (effects[k] < 0 && state.stats[k] < -effects[k]) return false;
779:   }
780:   return true;
781: }
782: function effectTags(effects = {}) {
783:   const out = [];
784:   for (const [k, label] of [['faith', 'Faith'], ['power', 'Power'], ['wisdom', 'Wisdom'], ['influence', 'Influence']]) {
785:     if (effects[k]) out.push(tagHtml(`${effects[k] > 0 ? '+' : ''}${effects[k]} ${t(label)}`, effects[k] > 0));
786:   }
787:   if (effects.followersPct) out.push(tagHtml(t('{n}% Souls', { n: (effects.followersPct > 0 ? '+' : '') + Math.round(effects.followersPct * 100) }), effects.followersPct > 0));
788:   if (effects.relic) out.push(tagHtml(t('+ Relic'), true));
789:   return out.join('');
790: }
