792: function openEventModal(rawEv) {
793:   const ev = localizedEvent(rawEv);
794:   openModal(`${closeBtn()}
795:     <div class="modal-kicker">${esc(t('Aeon {n} · Omen', { n: roman(state.aeon) }))}</div>
796:     <h2>${esc(ev.title)}</h2>
797:     <p class="modal-text">${esc(ev.text)}</p>
798:     <div class="choice-list">${ev.choices.map((c, i) => {
799:       const ok = affordableEffects(c.effects);
800:       return `<button class="choice" data-choice="${i}" ${ok ? '' : 'disabled'}>
801:         <span class="ch-label">${esc(c.label)}</span>
802:         <span class="ch-tags">${effectTags(c.effects)}</span>
