623: function renderBoard(stand, might) {
624:   const entries = [
625:     ...state.rivals.map(r => ({ name: r.name, epithet: r.epithet, pantheon: r.pantheon, domain: r.domain, might: r.might, player: false })),
626:     { name: 'YOU', might, domain: state.god.domain, pantheon: state.god.pantheon, epithet: state.god.epithet, player: true },
627:   ].sort((a, b) => b.might - a.might);
628:   const playerIndex = entries.findIndex(e => e.player);
629:   const rows = entries.map((e, i) => {
630:     const playerRank = i + 1;
631:     if (!e.player && i >= 20) return '';
632:     const dd = domainOf(e.domain);
633:     const prev = state.lastRanks ? state.lastRanks[e.player ? 'YOU' : e.name] : null;
634:     let trend = '';
635:     if (prev) {
636:       const diff = prev - playerRank;
637:       if (diff > 0) trend = `<span class="t-trend up">▲ ${diff}</span>`;
638:       else if (diff < 0) trend = `<span class="t-trend down">▼ ${Math.abs(diff)}</span>`;
639:       else trend = `<span class="t-trend">—</span>`;
640:     }
641:     const prow = e.player;
642:     return `<li class="throne${prow ? ' you' : ''}${playerRank <= 3 ? ' top' : ''}" ${prow ? '' : `data-rival="${state.rivals.findIndex(r => r.name === e.name)}"`}>
643:       <span class="t-rank">${playerRank}</span>
644:       <span class="t-sigil" style="color:${dd.color}">${icon(DOMAIN_ICONS[dd.id])}</span>
645:       <span class="t-info"><span class="t-name">${esc(prow ? state.god.name : e.name)}${prow ? `<span class="you-tag">${esc(t('YOU'))}</span>` : ''}</span><span class="t-sub">${esc(domainName(dd))} · ${esc(t(e.pantheon))}</span></span>
646:       <span class="t-might">${fmt(e.might)}${trend}</span>
647:     </li>`;
648:   }).join('');
649:   $('#leaderboard').innerHTML = rows;
650:   $('#boardCrown').innerHTML = icon('crown');
651:   $('#playerStanding').innerHTML = `<span class="standing-text">${esc(t('Your standing'))}</span><span class="standing-badge">#${stand.rank} <span style="color:var(--muted-2);font-size:9px">${esc(t('of {n}', { n: stand.total }))}</span></span>`;
652:   if (playerIndex >= 20) {
653:     const note = document.createElement('div');
654:     note.className = 'standing-text';
655:     note.style.padding = '6px 4px 0';
656:     note.innerHTML = t('You are outside the Twenty Thrones. <b>{n}</b> might.', { n: fmt(might) });
657:     $('#playerStanding').prepend(note);
658:   }
659: }
