499:   const age = ageOf();
500:   const mood = computeMood();
501:   const moodName = t(mood.charAt(0).toUpperCase() + mood.slice(1));
502:   const hudAvatar = $('#hudAvatar');
503:   if (hudAvatar) {
504:     hudAvatar.dataset.mood = mood;
505:     hudAvatar.style.setProperty('--mood', MOOD_COLORS[mood]);
506:     hudAvatar.title = t('Mood: {mood} · Age {age}', { mood: moodName, age });
