510:   $('#hudAvatarBadge').innerHTML = icon(DOMAIN_ICONS[d.id]);
511:   const moodLine = $('#moodLine');
512:   if (moodLine) {
513:     moodLine.dataset.mood = mood;
514:     moodLine.style.setProperty('--mood', MOOD_COLORS[mood]);
515:     moodLine.innerHTML = `<span class="mood-dot"></span><span>${esc(t('{mood} · {age} years', { mood: moodName, age }))}</span>`;
516:   }
517:   $('#hudName').textContent = state.god.name;
518:   $('#hudRank').textContent = rankName(rank);
519:   $('#hudEpithet').textContent = `${t(state.god.epithet)} · ${t(state.god.pantheon)} · ${ageLabel(age)}`;
520:   $('#hudMight').textContent = fmt(might);
521:   $('#hudStanding').textContent = '#' + stand.rank;
522:   $('#hudAeon').textContent = t('Aeon {n}', { n: roman(state.aeon) });
523:   $('#hudDomain').textContent = domainName(d);
524: 
525:   $('#gamePortrait').innerHTML = renderPortrait(state.god, { age });
526:   $('#cardName').textContent = state.god.name;
527:   $('#cardSub').textContent = `${rankName(rank)} · ${domainName(d)} · ${ageLabel(age)}`;
528:   $('#cardMight').textContent = fmt(might);
529:   const next = RANKS[state.rank + 1];
530:   const curNeed = rank.need;
531:   const pct = next ? Math.max(0, Math.min(100, ((might - curNeed) / (next.need - curNeed)) * 100)) : 100;
532:   $('#mightBar').style.width = pct + '%';
533:   if (next && might < next.need) {
534:     $('#mightNext').textContent = t('{n} more might to become {name}', { n: fmt(next.need - might), name: rankName(next) });
535:   } else if (next) {
536:     $('#mightNext').textContent = t('The way to {name} is open.', { name: rankName(next) });
537:   } else {
538:     $('#mightNext').textContent = t('You stand at the summit of the divine order.');
539:   }
540:   $('#cardFollowers').textContent = fmt(state.followers);
541:   const delta = state.followerDelta || 0;
542:   $('#followersTrend').textContent = delta > 0 ? `+${fmt(delta)}` : delta < 0 ? `${fmt(delta)}` : '';
543:   $('#followersTrend').className = 'trend' + (delta < 0 ? ' down' : '');
544: 
545:   $('#statGrid').innerHTML = ['faith', 'power', 'wisdom', 'influence'].map(k =>
546:     `<div class="stat-cell" title="${esc(t(k.charAt(0).toUpperCase() + k.slice(1)))}">${icon(STAT_ICONS[k])}<div><span class="sv">${fmt(state.stats[k])}</span><span class="sl">${esc(t(k))}</span></div></div>`).join('');
547: 
548:   const ascBtn = $('#ascendBtn');
549:   const ready = canAscend(state);
