551:     ascBtn.disabled = true;
552:     ascBtn.classList.remove('ready');
553:     ascBtn.innerHTML = `<span class="asc-main">${icon('crown')} ${esc(t('Supreme Architect'))}</span><span class="asc-sub">${esc(t('The summit is yours'))}</span>`;
554:   } else if (ready) {
555:     ascBtn.disabled = false;
556:     ascBtn.classList.add('ready');
557:     ascBtn.innerHTML = `<span class="asc-main">${icon('crown')} ${esc(t('Ascend to {name}', { name: rankName(next) }))}</span><span class="asc-sub">${esc(t('The heavens are watching'))}</span>`;
558:   } else {
559:     ascBtn.disabled = true;
560:     ascBtn.classList.remove('ready');
561:     ascBtn.innerHTML = `<span class="asc-main">${icon('crown')} ${esc(t('Ascend'))}</span><span class="asc-sub">${esc(t('{n} might required', { n: fmt(next.need - might) }))}</span>`;
