563: 
564:   $('#raceChips').innerHTML = state.races.map((r, i) =>
565:     `<button class="race-chip" data-race="${i}" title="${esc(t(r.traitName))}"><span class="dot" style="background:${r.color};color:${r.color}"></span>${esc(r.name)}</button>`).join('');
566:   $('#relicList').innerHTML = state.relics.length
