623: function renderBoard(stand, might) {
624:   const entries = [
625:     ...state.rivals.map(r => ({ name: r.name, epithet: r.epithet, pantheon: r.pantheon, domain: r.domain, might: r.might, player: false })),
626:     { name: 'YOU', might, domain: state.god.domain, pantheon: state.god.pantheon, epithet: state.god.epithet, player: true },
627:   ].sort((a, b) => b.might - a.might);
628:   const playerIndex = entries.findIndex(e => e.player);
629:   const rows = entries.map((e, i) => {
630:     const playerRank = i + 1;
631:     if (!e.player && i >= 20) return '';
632:     const dd = domainOf(e.domain);
633:     const prev = state.lastRanks ? state.lastRanks[e.player ? 'YOU' : e.name] : null;
634:     let trend = '';
635:     if (prev) {
636:       const diff = prev - playerRank;
637:       if (diff > 0) trend = `<span class="t-trend up">▲ ${diff}</span>`;
638:       else if (diff < 0) trend = `<span class="t-trend down">▼ ${Math.abs(diff)}</span>`;
639:       else trend = `<span class="t-trend">—</span>`;
