/* The mortal settlement */
.village-entry { display: flex; align-items: center; gap: 12px; width: 100%; padding: 10px 15px; text-align: left; color: var(--gold-hi); background: linear-gradient(110deg, rgba(125,99,66,.22), rgba(31,29,44,.8)); border: 1px solid var(--line-strong); border-radius: 12px; cursor: pointer; }
