.village-top h2 { font: 26px var(--serif); color: var(--gold-hi); margin: 0; }
.village-kicker { color: var(--gold-dim); text-transform: uppercase; letter-spacing: .18em; font-size: 9px; }
.village-back { background: transparent; color: var(--gold); border: 1px solid var(--line-strong); border-radius: 8px; padding: 8px 10px; cursor: pointer; font-size: 10px; }
