.village-scene svg { display: block; width: 100%; height: 100%; }
.village-scene-caption { position: absolute; inset: auto 0 0; padding: 30px 16px 12px; background: linear-gradient(transparent, rgba(12,12,19,.85)); }
.village-scene-caption span, .village-scene-caption strong { display: block; }
.village-scene-caption span { color: var(--gold); font-size: 9px; text-transform: uppercase; letter-spacing: .18em; }
.village-scene-caption strong { font: 21px var(--serif); color: #fff1d2; }
.village-intro { color: var(--muted); font: italic 14px var(--serif); margin: 16px 0; }
