.village-facts > div { background: rgba(255,255,255,.035); border: 1px solid var(--line); border-radius: 9px; padding: 10px; min-width: 0; }
.village-facts span, .village-facts strong { display: block; }
.village-facts span { font-size: 9px; color: var(--muted-2); text-transform: uppercase; letter-spacing: .09em; }
.village-facts strong { font: 16px var(--serif); color: var(--gold-hi); overflow-wrap: anywhere; margin-top: 4px; }
.village-note { font-size: 11px; color: var(--muted-2); line-height: 1.6; }
